const CA_I3_COST_ACCOUNTING = [
  {question:"Prime cost includes:",options:{A:"Direct material + Direct labour + Direct expenses",B:"Direct material only",C:"Direct labour + Factory overheads",D:"All indirect costs"},answer:"A",topic:"Cost Concepts",difficulty:"easy",explanation:"Prime cost = Direct Material + Direct Labour + Direct Expenses. It represents the basic cost of production without any overheads."},
  {question:"Factory overheads are also known as:",options:{A:"Administrative overheads",B:"Works overheads",C:"Selling overheads",D:"Distribution overheads"},answer:"B",topic:"Overheads",difficulty:"easy",explanation:"Factory overheads = Works overheads = Manufacturing overheads. They include all indirect costs incurred in the factory."},
  {question:"Under marginal costing, fixed costs are:",options:{A:"Included in product cost",B:"Treated as period costs",C:"Ignored",D:"Allocated to products"},answer:"B",topic:"Marginal Costing",difficulty:"medium",explanation:"Under marginal costing, only variable costs are included in product cost. Fixed costs are treated as period costs and charged to P&L."},
  {question:"The contribution margin is:",options:{A:"Sales - Total Cost",B:"Sales - Variable Cost",C:"Sales - Fixed Cost",D:"Sales - Direct Cost"},answer:"B",topic:"Marginal Costing",difficulty:"easy",explanation:"Contribution = Sales - Variable Cost. It contributes towards covering fixed costs and generating profit."},
  {question:"Break-even point in units is:",options:{A:"Fixed Cost / Selling Price",B:"Fixed Cost / Contribution per unit",C:"Variable Cost / Selling Price",D:"Total Cost / Units"},answer:"B",topic:"BEP",difficulty:"easy",explanation:"BEP (units) = Fixed Cost / Contribution per unit. At BEP, total revenue equals total cost."},
  {question:"In process costing, normal loss is:",options:{A:"Charged to costing P&L",B:"Charged to good units",C:"Ignored",D:"Charged to abnormal loss account"},answer:"B",topic:"Process Costing",difficulty:"medium",explanation:"Normal loss is absorbed by good production. The cost per unit increases because the same cost is spread over fewer good units."},
  {question:"Abnormal loss in process costing is:",options:{A:"Charged to good units",B:"Charged to Costing P&L",C:"Ignored",D:"Charged to next process"},answer:"B",topic:"Process Costing",difficulty:"medium",explanation:"Abnormal loss is valued at cost per unit and charged to Costing P&L. It is not borne by good production."},
  {question:"EOQ stands for:",options:{A:"Economic Order Quantity",B:"Estimated Order Quantity",C:"Equal Order Quantity",D:"Essential Order Quantity"},answer:"A",topic:"Material Control",difficulty:"easy",explanation:"EOQ = √(2AO/C), where A = Annual demand, O = Ordering cost per order, C = Carrying cost per unit."},
  {question:"Under job costing, costs are accumulated:",options:{A:"By process",B:"By job or batch",C:"By department",D:"By period"},answer:"B",topic:"Job Costing",difficulty:"easy",explanation:"Job costing accumulates costs for each individual job or batch, suitable for unique or customized products."},
  {question:"Standard costing is used for:",options:{A:"Recording actual costs",B:"Setting benchmarks and measuring variances",C:"Preparing budgets",D:"Auditing accounts"},answer:"B",topic:"Standard Costing",difficulty:"easy",explanation:"Standard costing sets predetermined costs (standards) and compares with actual costs to identify variances for control."},
  {question:"A favourable material price variance indicates:",options:{A:"Actual price > Standard price",B:"Actual price < Standard price",C:"Actual quantity > Standard quantity",D:"No difference"},answer:"B",topic:"Variance Analysis",difficulty:"medium",explanation:"Material Price Variance = (Standard Price - Actual Price) x Actual Quantity. If actual price is less than standard, variance is favourable."},
  {question:"Fixed overhead volume variance measures:",options:{A:"Efficiency of production",B:"Capacity utilization",C:"Both A and B",D:"Spending variance"},answer:"C",topic:"Variance Analysis",difficulty:"medium",explanation:"Volume Variance = (Standard output - Actual Output) x Standard Rate. It is further sub-divided into efficiency and capacity variances."},
  {question:"Cost Audit is compulsory for:",options:{A:"All companies",B:"Companies engaged in production",C:"Companies notified by Central Government",D:"Only government companies"},answer:"C",topic:"Cost Audit",difficulty:"medium",explanation:"As per Section 148 of Companies Act 2013, cost audit is applicable to companies notified by the Central Government."},
  {question:"The technique of costing used in hospitals is:",options:{A:"Job costing",B:"Process costing",C:"Operating/Service costing",D:"Contract costing"},answer:"C",topic:"Service Costing",difficulty:"easy",explanation:"Operating/Service costing is used in service industries like hospitals, transport, hotels where services are rendered rather than goods produced."},
  {question:"In contract costing, when work certified is more than 2/3 of contract price, profit is:",options:{A:"Not transferred to P&L",B:"Fully transferred to P&L",C:"Transferred proportionately to P&L",D:"Transferred to reserves"},answer:"C",topic:"Contract Costing",difficulty:"medium",explanation:"When work certified exceeds 2/3 of contract price, a proportionate profit is transferred to P&L based on cash received."}
];

