const CA_FIN2_SFM = [
  {question:"The Capital Asset Pricing Model (CAPM) formula is:",options:{A:"E(R) = Rf + β(Rm - Rf)",B:"E(R) = Rf + Rm",C:"E(R) = β x Rf",D:"E(R) = Rm - Rf"},answer:"A",topic:"CAPM",difficulty:"easy",explanation:"CAPM: E(Ri) = Rf + βi(Rm - Rf), where Rf = risk-free rate, β = systematic risk, Rm = market return."},
  {question:"Beta of the market portfolio is:",options:{A:"0",B:"1",C:"-1",D:"Infinity"},answer:"B",topic:"Beta",difficulty:"easy",explanation:"The beta of the market portfolio is always 1, as it represents the benchmark against which systematic risk is measured."},
  {question:"The Black-Scholes model is used for pricing:",options:{A:"Equity shares",B:"Bonds",C:"Options",D:"Futures"},answer:"C",topic:"Options",difficulty:"easy",explanation:"The Black-Scholes model is used for pricing European-style options using five input variables: S, K, T, r, and σ (volatility)."},
  {question:"A call option is in-the-money when:",options:{A:"Spot price > Strike price",B:"Spot price < Strike price",C:"Spot price = Strike price",D:"Time to expiry is zero"},answer:"A",topic:"Options",difficulty:"easy",explanation:"A call option is in-the-money when the current market (spot) price is above the exercise (strike) price."},
  {question:"The Sharpe ratio measures:",options:{A:"Systematic risk per unit of return",B:"Risk-adjusted return per unit of total risk",C:"Alpha of a portfolio",D:"Beta of a portfolio"},answer:"B",topic:"Portfolio",difficulty:"medium",explanation:"Sharpe Ratio = (Rp - Rf) / σp. It measures excess return per unit of total risk (standard deviation)."},
  {question:"In the Dividend Discount Model, if D1 = Rs 5, g = 5%, ke = 15%, the value of share is:",options:{A:"Rs 50",B:"Rs 33.33",C:"Rs 100",D:"Rs 25"},answer:"A",topic:"Valuation",difficulty:"medium",explanation:"P0 = D1/(ke - g) = 5/(0.15 - 0.05) = 5/0.10 = Rs 50."},
  {question:"Arbitrage is:",options:{A:"Buying high, selling low",B:"Risk-free profit from price differential",C:"Speculation",D:"Hedging"},answer:"B",topic:"Arbitrage",difficulty:"easy",explanation:"Arbitrage is the simultaneous purchase and sale of the same asset in different markets to profit from price differences with zero risk."},
  {question:"Duration of a bond measures:",options:{A:"Credit risk",B:"Interest rate risk / sensitivity of price to yield changes",C:"Default risk",D:"Liquidity risk"},answer:"B",topic:"Fixed Income",difficulty:"medium",explanation:"Macaulay duration measures the weighted average time to receive cash flows. Modified duration measures price sensitivity to yield changes."},
  {question:"The put-call parity relationship is:",options:{A:"C + PV(X) = P + S",B:"C - P = S + PV(X)",C:"C + S = P + PV(X)",D:"C = P + S"},answer:"A",topic:"Options",difficulty:"hard",explanation:"Put-Call Parity: C + PV(X) = P + S, where C = call price, P = put price, S = spot price, PV(X) = present value of strike price."},
  {question:"NPV and IRR give conflicting results when:",options:{A:"Projects are independent",B:"Projects have different scales or timing of cash flows",C:"Projects are mutually exclusive with same scale",D:"There is no capital rationing"},answer:"B",topic:"Capital Budgeting",difficulty:"medium",explanation:"NPV and IRR can conflict for mutually exclusive projects with different scales, timing, or lives. In such cases, NPV is preferred."},
  {question:"WACC is the:",options:{A:"Cost of equity only",B:"Weighted average cost of all sources of capital",C:"Cost of debt only",D:"Marginal cost of capital"},answer:"B",topic:"Cost of Capital",difficulty:"easy",explanation:"WACC = We x Ke + Wd x Kd(1-t) + Wp x Kp. It is the weighted average cost of equity, debt, and preference capital."},
  {question:"The Modigliani-Miller proposition (without taxes) states that:",options:{A:"Debt increases firm value",B:"Capital structure is irrelevant to firm value",C:"Equity is always cheaper",D:"100% debt is optimal"},answer:"B",topic:"Capital Structure",difficulty:"medium",explanation:"MM Proposition I (no taxes) states that the value of a firm is independent of its capital structure — the total value is the same regardless of debt-equity mix."},
  {question:"Economic Value Added (EVA) = NOPAT - (Capital x WACC). A positive EVA indicates:",options:{A:"Firm is destroying value",B:"Firm is creating shareholder value",C:"Firm has no debt",D:"Firm is overvalued"},answer:"B",topic:"EVA",difficulty:"easy",explanation:"Positive EVA means the firm is earning more than its cost of capital, thereby creating value for shareholders."},
  {question:"Interest Rate Swap involves:",options:{A:"Exchanging equity for debt",B:"Exchanging fixed interest payments for floating",C:"Exchanging currencies",D:"Exchanging commodities"},answer:"B",topic:"Derivatives",difficulty:"easy",explanation:"An interest rate swap involves exchanging fixed-rate interest payments for floating-rate payments (or vice versa) on a notional principal."},
  {question:"Exchange Rate Risk can be hedged using:",options:{A:"Forward contracts only",B:"Options only",C:"Futures only",D:"All of the above — forwards, futures, options, and swaps"},answer:"D",topic:"Forex",difficulty:"easy",explanation:"Exchange rate risk can be hedged using various derivatives: forward contracts, currency futures, currency options, and currency swaps."}
];

